  "inlineSchema": "// Prisma Schema para Denuncias Service  \n// Base de datos: denuncias_db\n// Responsabilidad: Denuncias, evidencias, historial, reglas\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Denuncia {\n  id            String            @id @default(uuid())\n  codigoAnonimo String            @unique\n  titulo        String\n  descripcion   String\n  categoria     CategoriaDenuncia\n  estado        EstadoDenuncia    @default(PENDIENTE)\n  prioridad     Prioridad         @default(MEDIA)\n\n  // Referencias a otros servicios (solo IDs, no relaciones FK)\n  denuncianteId String? // Usuario del auth-service\n  supervisorId  String? // Usuario del auth-service\n\n  ubicacionGeneral String?\n  derivadaA        String?\n  fechaDerivacion  DateTime?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  // Relaciones locales\n  evidencias Evidencia[]\n  historial  HistorialDenuncia[]\n\n  @@map(\"denuncias\")\n}\n\nmodel Evidencia {\n  id             String   @id @default(uuid())\n  denunciaId     String\n  nombreOriginal String\n  nombreCifrado  String\n  tipo           String\n  tamano         Int\n  rutaCifrada    String\n  createdAt      DateTime @default(now())\n  denuncia       Denuncia @relation(fields: [denunciaId], references: [id], onDelete: Cascade)\n\n  @@map(\"evidencias\")\n}\n\nmodel HistorialDenuncia {\n  id             String         @id @default(uuid())\n  denunciaId     String\n  estadoAnterior EstadoDenuncia\n  estadoNuevo    EstadoDenuncia\n  comentario     String?\n  realizadoPor   String // Usuario ID del auth-service\n  createdAt      DateTime       @default(now())\n  denuncia       Denuncia       @relation(fields: [denunciaId], references: [id], onDelete: Cascade)\n\n  @@map(\"historial_denuncias\")\n}\n\nmodel ReglaSupervisor {\n  id           String            @id @default(uuid())\n  nombre       String\n  descripcion  String?\n  prioridad    Int               @default(0) // 0=BAJA, 1=MEDIA, 2=ALTA, 3=URGENTE\n  activa       Boolean           @default(true)\n  categoria    CategoriaDenuncia\n  supervisorId String // Usuario ID del auth-service\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  @@unique([categoria, prioridad, activa])\n  @@index([activa])\n  @@index([categoria])\n  @@index([prioridad])\n  @@index([supervisorId])\n  @@map(\"reglas_supervisor\")\n}\n\nenum CategoriaDenuncia {\n  ACOSO_LABORAL\n  DISCRIMINACION\n  FALTA_DE_PAGO\n  ACOSO_SEXUAL\n  VIOLACION_DERECHOS\n  OTRO\n}\n\nenum EstadoDenuncia {\n  PENDIENTE\n  EN_REVISION\n  APROBADA\n  DERIVADA\n  CERRADA\n  RECHAZADA\n}\n\nenum Prioridad {\n  BAJA\n  MEDIA\n  ALTA\n  URGENTE\n}\n",
